/* ================= WORD GAMES: Wordle, Hangman, Word Connect ================= */
let _wordleOK = null, _dictSet = null;
const wordleOK = () => _wordleOK || (_wordleOK = new Set(WORDLE_OK.split(' ')));
const dictSet = () => _dictSet || (_dictSet = new Set(DICT_RAW.split(' ')));
const pickFrom = a => a[rand(a.length)];
const LETTER_ROWS = ['qwertyuiop', 'asdfghjkl', '*zxcvbnm#'];   // * = Enter, # = Delete

function wordleEval(guess, ans){
  const res = Array(guess.length).fill(0), left = {};
  for (let i = 0; i < ans.length; i++) { if (guess[i] === ans[i]) res[i] = 2; else left[ans[i]] = (left[ans[i]] || 0) + 1; }
  for (let i = 0; i < guess.length; i++) if (!res[i] && left[guess[i]] > 0) { res[i] = 1; left[guess[i]]--; }
  return res;
}
/* Hard level: letters already found must be used again, greens in the same place. Returns an error text or ''. */
function wordleHardCheck(guess, rows){
  for (const r of rows) {
    const need = {};
    for (let i = 0; i < 5; i++) {
      if (r.ev[i] === 2 && guess[i] !== r.w[i]) return 'Letter ' + (i + 1) + ' must be ' + r.w[i].toUpperCase();
      if (r.ev[i] > 0) need[r.w[i]] = (need[r.w[i]] || 0) + 1;
    }
    for (const c in need) if (guess.split(c).length - 1 < need[c]) return 'Guess must contain ' + c.toUpperCase();
  }
  return '';
}
